package faker.data;

import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import static faker.data.GenerationBatchTest.*;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
class PortableSchemeTest {
    static final Path DIR=GenerationBatchTest.directory();
    @Autowired TestRestTemplate http;
    @Autowired JdbcTemplate ledger;
    @org.springframework.boot.test.mock.mockito.SpyBean faker.data.scheme.FakerSchemeService schemeService;
    @DynamicPropertySource static void properties(DynamicPropertyRegistry p){p.add("faker.data-dir",DIR::toString);}
    Map<String,Object> source(String password){return m("type","MYSQL","url","jdbc:mysql://127.0.0.1:1/no-contact?connectTimeout=200&socketTimeout=200","username","private-user","password",password);}
    @SuppressWarnings("unchecked") Map<String,Object> exported() {
        Map<String,Object> extension=m("code","EXT.FIELD","extension","demo-codec","extensionParameters",m("sourceField","id","binaryEncoding","base64","privatePath","C:/private/codec"));
        Map table=table("portable_rows",1,col("id","java.lang.String",m("code","FIX.UUID")),fixed("password","java.lang.String","column-secret"),col("payload","byte[]",extension),fixed("note","java.lang.String","connection-secret"));
        Map response=http.postForObject("/scheme/save",m("name","Private-"+UUID.randomUUID(),"dataSource",source("connection-secret"),"tables",Arrays.asList(table)),Map.class);assertEquals(0,response.get("code"));Object id=response.get("data");response=http.getForObject("/scheme/"+id+"/export",Map.class);assertEquals(0,response.get("code"),response.toString());return (Map<String,Object>)response.get("data");
    }
    @SuppressWarnings("unchecked") Map<String,Object> replacements(Map<String,Object> document){Map<String,Object> result=new LinkedHashMap<>();for(Map<String,Object> value:(List<Map<String,Object>>)document.get("requiredLocalValues")){String pointer=(String)value.get("pointer");result.put(pointer,pointer.endsWith("/regs")?Arrays.asList(m("code","RES.INPUTAREA","inputs",Arrays.asList(m("value","bound-column-secret","weight",1)))):pointer.contains("privatePath")?"C:/local-only":"bound-note-secret");}return result;}
    Map<String,Object> importing(Map<String,Object> document,String name,boolean trusted){return m("document",document,"name",name,"dataSource",source("new-connection-secret"),"replacements",replacements(document),"confirmTrustedCode",trusted);}
    @Test void safeExportOmitsConnectionCredentialsExecutablesAndPrivateValues(){Map document=exported();String text=document.toString();for(String secret:Arrays.asList("private-user","connection-secret","column-secret","C:/private/codec","jdbc:mysql"))assertFalse(text.contains(secret),text);assertEquals("faker-data.scheme",document.get("format"));assertEquals(1,document.get("formatVersion"));assertEquals("local",document.get("connectionRef"));assertEquals(3,((List)document.get("requiredLocalValues")).size());assertEquals(Arrays.asList("demo-codec"),document.get("requiredExtensions"));assertEquals(true,document.get("trustedCodeRequired"));assertFalse(text.contains("refOtherTables"));assertFalse(text.contains("depended"));}
    @SuppressWarnings("unchecked") @Test void importsWithExplicitLocalBindingsWithoutConnectingOrGeneratingAndMasksAgain(){Map<String,Object> document=exported();int before=ledger.queryForObject("SELECT COUNT(*) FROM faker_task",Integer.class);Map response=http.postForObject("/scheme/import",importing(document,"Imported-"+UUID.randomUUID(),true),Map.class);assertEquals(0,response.get("code"),response.toString());Map imported=(Map)response.get("data");Object id=imported.get("schemeId");String stored=(String)((Map)http.getForObject("/scheme/"+id,Map.class).get("data")).get("tablesJson");assertTrue(stored.contains("bound-column-secret"));assertTrue(stored.contains("bound-note-secret"));assertEquals(before,ledger.queryForObject("SELECT COUNT(*) FROM faker_task",Integer.class));Map again=http.getForObject("/scheme/"+id+"/export",Map.class);assertEquals(0,again.get("code"),again.toString());for(String secret:Arrays.asList("bound-column-secret","bound-note-secret","C:/local-only","new-connection-secret"))assertFalse(again.toString().contains(secret),again.toString());}
    @Test void missingBindingsTrustAndFutureVersionsFailClosed(){Map<String,Object> document=exported();Map body=importing(document,"Missing-"+UUID.randomUUID(),true);body.put("replacements",Collections.emptyMap());Map response=http.postForObject("/scheme/import",body,Map.class);assertNotEquals(0,response.get("code"));assertTrue(response.toString().contains("SCHEME_VALUES_REQUIRED"),response.toString());response=http.postForObject("/scheme/import",importing(document,"Untrusted-"+UUID.randomUUID(),false),Map.class);assertNotEquals(0,response.get("code"));assertTrue(response.toString().contains("SCHEME_TRUST_CONFIRMATION_REQUIRED"));document.put("formatVersion",999);response=http.postForObject("/scheme/import",importing(document,"Future-"+UUID.randomUUID(),true),Map.class);assertNotEquals(0,response.get("code"));assertTrue(response.toString().contains("SCHEME_VERSION_UNSUPPORTED"));}
    @SuppressWarnings("unchecked") @Test void importDoesNotOverwriteUnlessExplicitlyRequested(){Map<String,Object> document=exported();Map body=importing(document,"Conflict-"+UUID.randomUUID(),true);Map first=http.postForObject("/scheme/import",body,Map.class);assertEquals(0,first.get("code"),first.toString());Map second=http.postForObject("/scheme/import",body,Map.class);assertNotEquals(0,second.get("code"));assertTrue(second.toString().contains("SCHEME_NAME_CONFLICT"),second.toString());body.put("replaceExisting",true);Map replaced=http.postForObject("/scheme/import",body,Map.class);assertEquals(0,replaced.get("code"),replaced.toString());assertEquals(((Map)first.get("data")).get("schemeId"),((Map)replaced.get("data")).get("schemeId"));}
    @Test void importedMetadataAndPointersCannotSmuggleRawConnectionsOrArbitraryPatches(){Map<String,Object> document=exported();document.put("dataSource",source("should-not-import"));Map response=http.postForObject("/scheme/import",importing(document,"Bad-root",true),Map.class);assertNotEquals(0,response.get("code"));document.remove("dataSource");Map body=importing(document,"Bad-pointer",true);((Map)body.get("replacements")).put("/formatVersion",2);response=http.postForObject("/scheme/import",body,Map.class);assertNotEquals(0,response.get("code"));}
    @SuppressWarnings("unchecked") @Test void exportReadsSchemeAndPrivatePointersFromTheSameLocalSnapshot() throws Exception {
        Map<String,Object> first=exported();((List)((Map)((List)first.get("tables")).get(0)).get("columns")).add(fixed("alternate_note","java.lang.String","public"));
        com.fasterxml.jackson.databind.ObjectMapper mapper=new com.fasterxml.jackson.databind.ObjectMapper();Map<String,Object> second=mapper.readValue(mapper.writeValueAsString(first),new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});
        List<Map> columns=(List<Map>)((Map)((List)second.get("tables")).get(0)).get("columns");((Map)((List)((Map)((List)columns.get(3).get("regs")).get(0)).get("inputs")).get(0)).put("value","public");((Map)((List)((Map)((List)columns.get(4).get("regs")).get(0)).get("inputs")).get(0)).put("value",null);
        for(Map redaction:(List<Map>)second.get("requiredLocalValues"))if(((String)redaction.get("pointer")).contains("/columns/3/"))redaction.put("pointer",((String)redaction.get("pointer")).replace("/columns/3/","/columns/4/"));
        String name="Snapshot-"+UUID.randomUUID();Map created=http.postForObject("/scheme/import",importing(first,name,true),Map.class);assertEquals(0,created.get("code"),created.toString());long id=((Number)((Map)created.get("data")).get("schemeId")).longValue();
        java.util.concurrent.CountDownLatch captured=new java.util.concurrent.CountDownLatch(1),resume=new java.util.concurrent.CountDownLatch(1);
        org.mockito.Mockito.doAnswer(call->{Object result=call.callRealMethod();captured.countDown();if(!resume.await(5,java.util.concurrent.TimeUnit.SECONDS))throw new IllegalStateException("Fixture barrier timed out");return result;}).when(schemeService).getById(id);
        java.util.concurrent.ExecutorService pool=java.util.concurrent.Executors.newSingleThreadExecutor();
        try{java.util.concurrent.Future<Map> exporting=pool.submit(()->http.getForObject("/scheme/"+id+"/export",Map.class));assertTrue(captured.await(5,java.util.concurrent.TimeUnit.SECONDS));Map replace=importing(second,name,true);replace.put("replaceExisting",true);Map response=http.postForObject("/scheme/import",replace,Map.class);assertEquals(0,response.get("code"),response.toString());resume.countDown();Map exported=exporting.get(5,java.util.concurrent.TimeUnit.SECONDS);assertEquals(0,exported.get("code"),exported.toString());assertFalse(exported.toString().contains("bound-note-secret"),exported.toString());}
        finally{resume.countDown();pool.shutdownNow();org.mockito.Mockito.reset(schemeService);}
    }
    @SuppressWarnings("unchecked") @Test void reservedTypeMetadataIsRejectedAndDeletingSchemeRemovesPrivatePointers(){Map<String,Object> document=exported();Map rule=(Map)((List)((Map)((List)((Map)((List)document.get("tables")).get(0)).get("columns")).get(2)).get("regs")).get(0);((Map)rule.get("extensionParameters")).put("@type","java.lang.String");Map rejected=http.postForObject("/scheme/import",importing(document,"No-types",true),Map.class);assertNotEquals(0,rejected.get("code"));assertTrue(rejected.toString().contains("SCHEME_RESERVED_TYPE_METADATA"),rejected.toString());Map created=http.postForObject("/scheme/import",importing(exported(),"Delete-"+UUID.randomUUID(),true),Map.class);assertEquals(0,created.get("code"));long id=((Number)((Map)created.get("data")).get("schemeId")).longValue();assertTrue(ledger.queryForObject("SELECT COUNT(*) FROM faker_scheme_private_path WHERE scheme_id=?",Integer.class,id)>0);http.delete("/scheme/"+id);assertEquals(0,ledger.queryForObject("SELECT COUNT(*) FROM faker_scheme_private_path WHERE scheme_id=?",Integer.class,id));}
    @SuppressWarnings("unchecked") @Test void sourceTreeOwnershipAndVirtualFieldsSurviveWithoutPlannerMovingBindings() throws Exception {
        Map marker=fixed("role_marker","java.lang.String","INPUT");marker.put("virtual",true);Map root=table("portable_advanced",1,col("id","java.lang.String",m("code","FIX.UUID")),fixed("password","java.lang.String","private-column"),col("parent_id","java.lang.String",m("code","STRUCT.TREE_PARENT")),col("customer_id","java.lang.String",m("code","REF.OTHER_TABLE","refOtherTableColumn",Arrays.asList("portable_lookup","id"))),marker);
        root.put("treeConfig",m("nodeField","id","parentRefField","parent_id","maxDepth",2,"minRoots",1,"maxRoots",1,"minChildrenPerNode",1,"maxChildrenPerNode",1));root.put("ownership",m("mutableColumns",Arrays.asList("customer_id"),"derivedRows",Arrays.asList(m("table","portable_descendants","join",m("parent_id","id"),"where",m("kind","fixture")))));
        Map lookup=table("portable_lookup",0,col("id","java.lang.String"));lookup.put("existingData",m("where",m("enabled",1),"maxRows",10));Map saved=http.postForObject("/scheme/save",m("name","Advanced-"+UUID.randomUUID(),"dataSource",source("connection-secret"),"tables",Arrays.asList(root,lookup)),Map.class);Map document=(Map)http.getForObject("/scheme/"+saved.get("data")+"/export",Map.class).get("data");assertNotNull(document);
        Map body=importing(document,"Advanced imported-"+UUID.randomUUID(),false);((Map)body.get("replacements")).put("/tables/1/existingData/where/enabled",1);Map imported=http.postForObject("/scheme/import",body,Map.class);assertEquals(0,imported.get("code"),imported.toString());long id=((Number)((Map)imported.get("data")).get("schemeId")).longValue();String stored=(String)((Map)http.getForObject("/scheme/"+id,Map.class).get("data")).get("tablesJson");List<Map> tables=new com.fasterxml.jackson.databind.ObjectMapper().readValue(stored,new com.fasterxml.jackson.core.type.TypeReference<List<Map>>(){});
        assertEquals("portable_advanced",tables.get(0).get("name"));assertNotNull(tables.get(0).get("treeConfig"));assertNotNull(tables.get(0).get("ownership"));assertTrue(((List<Map>)tables.get(0).get("columns")).stream().anyMatch(c->Boolean.TRUE.equals(c.get("virtual"))));Map again=http.getForObject("/scheme/"+id+"/export",Map.class);assertEquals(0,again.get("code"),again.toString());assertFalse(again.toString().contains("bound-column-secret"));
    }
    @SuppressWarnings("unchecked") @Test void purePortableValidationNeverCallsFunctionProvidersOrEvaluatesJava(){
        Map condition=m("code","COND.EXPR","condition","contains('fixture','fix')","onTrue",Arrays.asList(m("code","FIX.UUID")));Map response=http.postForObject("/scheme/save",m("name","No-callback-"+UUID.randomUUID(),"dataSource",source("connection-secret"),"tables",Arrays.asList(table("portable_rows",1,col("id","java.lang.String",condition)))),Map.class);System.clearProperty("faker.portable.callback");System.clearProperty("faker.portable.java");
        try{Map exported=http.getForObject("/scheme/"+response.get("data")+"/export",Map.class);assertEquals(0,exported.get("code"),exported.toString());assertNull(System.getProperty("faker.portable.callback"));Map document=(Map)exported.get("data");Map rule=(Map)((List)((Map)((List)((Map)((List)document.get("tables")).get(0)).get("columns")).get(0)).get("regs")).get(0);rule.put("condition","T(java.lang.System).setProperty('faker.portable.java','executed') == null");document.put("trustedCodeRequired",false);Map body=m("document",document,"name","Needs-trust-"+UUID.randomUUID(),"dataSource",source("new-secret"),"replacements",Collections.emptyMap());Map refused=http.postForObject("/scheme/import",body,Map.class);assertNotEquals(0,refused.get("code"));assertTrue(refused.toString().contains("SCHEME_TRUST_CONFIRMATION_REQUIRED"),refused.toString());body.put("confirmTrustedCode",true);Map imported=http.postForObject("/scheme/import",body,Map.class);assertEquals(0,imported.get("code"),imported.toString());assertNull(System.getProperty("faker.portable.callback"));assertNull(System.getProperty("faker.portable.java"));}
        finally{System.clearProperty("faker.portable.callback");System.clearProperty("faker.portable.java");}
    }
    @org.springframework.boot.test.context.TestConfiguration static class Callbacks {
        @org.springframework.context.annotation.Bean faker.data.service.generate.SpelFunctionProvider canary(){return new faker.data.service.generate.SpelFunctionProvider(){public void register(org.springframework.expression.spel.support.StandardEvaluationContext context){System.setProperty("faker.portable.callback","called");}public Set<String> getFunctionNames(){System.setProperty("faker.portable.callback","called");return Collections.singleton("customCanary");}};}
    }
}
